import { loadFont } from "@remotion/google-fonts/Outfit";
import React from "react";
import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// VINÍCIUS DENTISTA — prótese flexível. A narração é a própria fala da dentista no vídeo enviado (video-1.mp4, horizontal
// 832×464): ela aparece em cima com o lettering embaixo, e as cenas desenhadas (prótese, preço, sorriso) entram nos trechos
// em que a fala apresenta o produto. Sem logo nem cores do cliente: paleta clínica própria (creme, verde-petróleo, gengiva
// rosada), letra Outfit. Tempos da fala em segundos do vídeo original; o corte começa em 1,3 s (silêncio inicial).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const VN_FPS = 30;
const OFF = 1.3;
const S = (x: number) => x - OFF;
export const VN_DUR = 51.0;
export const VN_FRAMES = Math.round(VN_DUR * VN_FPS);

const CREAM = "#F6F1EA";
const INK = "#13272A";
const TEAL = "#0E8C86";
const TEAL_D = "#0A5E5A";
const GUM = "#EE8FA3";
const GUM_D = "#D7687F";
const WA = "#25D366";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

// ───────── cenas (tempo do vídeo final) ─────────
const A0 = 0, A1 = S(8.4); // gancho: motion até RET, depois a fala
const RET = S(3.3); // volta para ela logo depois do "sem dente?"
const B1 = S(19.3); // prótese desenhada
const C1 = S(24.8); // fala: implante
const D1 = S(33.3); // preço desenhado
const E1 = S(39.0); // fala: medo de dentista
const F1 = S(45.55); // sorriso desenhado
const G1 = S(48.74); // fala: chamada
// fim: cartão final até VN_DUR

// ───────── lettering ─────────
type W = [string, number, boolean?]; // palavra, tempo na fala original, destaque
const Words: React.FC<{ t: number; items: W[]; size: number; dark?: boolean; width?: number; tagColor?: string }> = ({ t, items, size, dark, width = 860, tagColor = TEAL }) => (
  <div style={{ width, display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "center", columnGap: size * 0.26, rowGap: size * 0.16 }}>
    {items.map(([w, at, tag], i) => {
      const a = S(at);
      const e = interpolate(t, [a, a + 0.28], [0, 1], { ...cl, easing: OUT });
      const p = interpolate(t, [a, a + 0.36], [0, 1], { ...cl, easing: BACK });
      return (
        <span key={i} style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.01em", display: "inline-block", color: tag ? "#FFFFFF" : dark ? INK : "#FFFFFF", opacity: e, transform: `translateY(${((1 - e) * size * 0.4).toFixed(1)}px) scale(${tag ? (0.82 + 0.18 * p).toFixed(3) : 1})`, background: tag ? tagColor : undefined, padding: tag ? `${size * 0.08}px ${size * 0.2}px ${size * 0.12}px` : undefined, borderRadius: tag ? size * 0.22 : undefined, boxShadow: tag ? `0 10px 30px ${tagColor}55` : undefined, textShadow: tag || dark ? "none" : "0 4px 18px rgba(0,0,0,0.55)" }}>
          {w}
        </span>
      );
    })}
  </div>
);
// frases que se revezam no mesmo lugar: a anterior sai inteira antes de a próxima entrar
type Phrase = { items: W[]; end: number; size?: number };
const Slot: React.FC<{ t: number; top: number; phrases: Phrase[]; dark?: boolean; width?: number }> = ({ t, top, phrases, dark, width }) => (
  <>
    {phrases.map((p, i) => {
      const a = S(p.items[0][1]) - 0.02;
      const b = S(p.end);
      if (t < a || t >= b) return null;
      const x = interpolate(t, [b - 0.14, b], [0, 1], cl);
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top, height: 0, display: "flex", justifyContent: "center", alignItems: "center", opacity: 1 - x, transform: `scale(${(1 - 0.08 * x).toFixed(3)})` }}>
          <Words t={t} items={p.items} size={p.size ?? 104} dark={dark} width={width} />
        </div>
      );
    })}
  </>
);
const Label: React.FC<{ children: React.ReactNode; color?: string; size?: number; style?: React.CSSProperties }> = ({ children, color = TEAL, size = 40, style }) => (
  <div style={{ fontFamily: F, fontWeight: 700, fontSize: size, color, letterSpacing: "0.22em", textTransform: "uppercase", whiteSpace: "nowrap", ...style }}>{children}</div>
);

// ───────── fala: vídeo dela em cima, faixa escura embaixo ─────────
const VH = 1500;
const VW = (832 * VH) / 464;
const Footage: React.FC<{ t: number; a: number; b: number; z: [number, number]; drift?: number; punches?: number[] }> = ({ t, a, b, z, drift = 0, punches = [] }) => {
  if (t < a || t >= b) return null;
  const base = z[0] + (z[1] - z[0]) * lin(t, a, b);
  const punch = punches.reduce((s, p) => s + 0.05 * Math.exp(-Math.max(0, t - S(p)) * 5) * (t >= S(p) ? 1 : 0), 0);
  const from = a;
  return (
    <AbsoluteFill style={{ background: "#0B1719", overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: VH, overflow: "hidden", transform: `scale(${(base + punch).toFixed(4)}) translateX(${(drift * (lin(t, a, b) - 0.5)).toFixed(1)}px)`, transformOrigin: "50% 38%" }}>
        <Sequence from={Math.round(from * VN_FPS)} layout="none">
          <OffthreadVideo src={staticFile("vinicius/video-1.mp4")} trimBefore={Math.round((from + OFF) * VN_FPS)} muted style={{ position: "absolute", top: 0, left: 540 - VW / 2, width: VW, height: VH, filter: "saturate(1.04) contrast(1.04)" }} />
        </Sequence>
      </div>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(11,23,25,0.25) 0%, rgba(11,23,25,0) 16%, rgba(11,23,25,0) 52%, rgba(11,23,25,0.75) 68%, #0B1719 80%)" }} />
    </AbsoluteFill>
  );
};

// ───────── fundo e câmera das cenas desenhadas ─────────
const Plain: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 55% at ${(50 + Math.sin(t * 0.6) * 18).toFixed(1)}% ${(40 + Math.cos(t * 0.5) * 10).toFixed(1)}%, #FFFFFF 0%, ${CREAM} 70%, #EDE5DA 100%)` }} />
);
const Cam: React.FC<{ t: number; a: number; b: number; mode: number; children: React.ReactNode }> = ({ t, a, b, mode, children }) => {
  if (t < a || t >= b) return null;
  const p = lin(t, a, b);
  const tr =
    mode === 0
      ? `translate(${(Math.sin(t * 1.1) * 10).toFixed(1)}px, ${((1 - p) * 40).toFixed(1)}px) scale(${(0.93 + 0.09 * p).toFixed(4)})`
      : mode === 1
        ? `translate(${((0.5 - p) * 60).toFixed(1)}px, ${(Math.cos(t * 1.2) * 8).toFixed(1)}px) scale(${(1.06 - 0.06 * p).toFixed(4)}) rotate(${((0.5 - p) * 1.6).toFixed(2)}deg)`
        : `translate(${(Math.cos(t * 0.9) * 12).toFixed(1)}px, ${((p - 0.5) * -50).toFixed(1)}px) scale(${(0.96 + 0.07 * p).toFixed(4)})`;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Plain t={t} />
      <AbsoluteFill style={{ transform: tr, transformOrigin: "50% 42%" }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── desenhos ─────────
// prótese flexível vista de cima: base de gengiva rosada em ferradura, dentes brancos encaixados; `flex` aperta e solta a peça
const Tooth: React.FC<{ x: number; y: number; w: number; h: number; r: number }> = ({ x, y, w, h, r }) => (
  <g transform={`translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${r.toFixed(1)})`}>
    <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={w * 0.38} fill="#FFFFFF" stroke="#D9E2E4" strokeWidth={3} />
    <rect x={-w / 2 + 8} y={-h / 2 + 7} width={w * 0.28} height={h * 0.5} rx={6} fill="#FFFFFF" opacity={0.9} />
    <path d={`M${-w * 0.22} ${h * 0.12} Q0 ${h * 0.3} ${w * 0.22} ${h * 0.12}`} stroke="#E4EAEC" strokeWidth={3} fill="none" />
  </g>
);
const Prosthesis: React.FC<{ flex?: number; teethIn?: number }> = ({ flex = 0, teethIn = 1 }) => {
  const cx = 300, cy = 470, rx = 230 * (1 - 0.16 * flex), ry = 330 * (1 + 0.04 * flex);
  const pt = (u: number) => {
    const a = u * (Math.PI / 2) * 1.02;
    return [cx + rx * Math.sin(a), cy - ry * Math.cos(a)] as const;
  };
  const ang = (u: number) => {
    const [x0, y0] = pt(u - 0.01), [x1, y1] = pt(u + 0.01);
    return (Math.atan2(y1 - y0, x1 - x0) * 180) / Math.PI;
  };
  const d = Array.from({ length: 61 }, (_, i) => -1 + (2 * i) / 60).map((u, i) => `${i ? "L" : "M"}${pt(u)[0].toFixed(1)} ${pt(u)[1].toFixed(1)}`).join(" ");
  const teeth: [number, number, number][] = [[-0.9, 92, 84], [-0.71, 88, 80], [-0.52, 74, 72], [-0.34, 66, 70], [-0.12, 70, 64], [0.12, 70, 64], [0.34, 66, 70], [0.52, 74, 72], [0.71, 88, 80], [0.9, 92, 84]];
  return (
    <svg width={600} height={520} viewBox="0 0 600 520" style={{ overflow: "visible" }}>
      <path d={d} stroke={GUM_D} strokeOpacity={0.35} strokeWidth={150} fill="none" strokeLinecap="round" transform="translate(0 10)" />
      <path d={d} stroke={GUM} strokeOpacity={0.92} strokeWidth={138} fill="none" strokeLinecap="round" />
      <path d={d} stroke="#FFC3CF" strokeOpacity={0.55} strokeWidth={34} fill="none" strokeLinecap="round" transform="translate(-6 -10)" />
      {teeth.map(([u, w, h], i) => {
        const [x, y] = pt(u);
        const e = interpolate(teethIn * 10 - i, [0, 1], [0, 1], cl);
        return (
          <g key={i} opacity={e} transform={`translate(0 ${((1 - e) * -40).toFixed(1)})`}>
            <Tooth x={x} y={y} w={w} h={h} r={ang(u)} />
          </g>
        );
      })}
    </svg>
  );
};
// grampo de metal riscado
const Clasp: React.FC<{ strike: number }> = ({ strike }) => (
  <svg width={300} height={300} viewBox="0 0 300 300">
    <circle cx={150} cy={150} r={140} fill="#FFFFFF" stroke="#E5DED4" strokeWidth={4} />
    <path d="M150 62 C112 62 96 84 98 118 C100 150 108 180 118 216 C124 236 140 236 142 214 L146 186 C147 176 153 176 154 186 L158 214 C160 236 176 236 182 216 C192 180 200 150 202 118 C204 84 188 62 150 62 Z" fill="#FFFFFF" stroke="#CFD8DA" strokeWidth={5} />
    <path d="M86 132 Q150 168 214 132" stroke="#8E9AA0" strokeWidth={14} fill="none" strokeLinecap="round" />
    <path d="M86 132 L80 112 M214 132 L220 112" stroke="#8E9AA0" strokeWidth={14} strokeLinecap="round" />
    <line x1={62} y1={62} x2={62 + 176 * strike} y2={62 + 176 * strike} stroke="#E0475B" strokeWidth={20} strokeLinecap="round" />
  </svg>
);
// etiqueta de preço com visto
const Tag: React.FC = () => (
  <svg width={360} height={300} viewBox="0 0 360 300">
    <path d="M40 60 Q40 30 70 30 L230 30 L330 150 L230 270 L70 270 Q40 270 40 240 Z" fill={TEAL} />
    <circle cx={250} cy={150} r={20} fill={CREAM} />
    <path d="M95 152 L135 192 L205 112" stroke="#FFFFFF" strokeWidth={26} fill="none" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
// carteira com moeda caindo dentro
const Wallet: React.FC<{ coin: number }> = ({ coin }) => (
  <svg width={420} height={360} viewBox="0 0 420 360" style={{ overflow: "visible" }}>
    <g transform={`translate(0 ${(-170 + 190 * coin).toFixed(1)})`} opacity={coin < 0.98 ? 1 : 0}>
      <circle cx={210} cy={110} r={58} fill="#FFFFFF" stroke={TEAL} strokeWidth={12} />
      <circle cx={210} cy={110} r={34} fill="none" stroke={TEAL} strokeWidth={7} opacity={0.55} />
    </g>
    <rect x={40} y={130} width={340} height={210} rx={40} fill={INK} />
    <rect x={40} y={130} width={340} height={70} rx={34} fill={TEAL_D} />
    <rect x={270} y={210} width={130} height={80} rx={26} fill={TEAL} />
    <circle cx={312} cy={250} r={14} fill={CREAM} />
  </svg>
);
// cartão com as parcelas acendendo uma a uma
const Card: React.FC<{ t: number; at: number }> = ({ t, at }) => (
  <svg width={520} height={420} viewBox="0 0 520 420">
    <rect x={20} y={20} width={480} height={290} rx={36} fill={INK} />
    <rect x={20} y={80} width={480} height={56} fill={TEAL_D} />
    <rect x={64} y={180} width={86} height={62} rx={14} fill="#E3C27A" />
    <rect x={190} y={198} width={190} height={22} rx={11} fill="#3B5458" />
    {[0, 1, 2, 3].map((i) => {
      const e = k(t, at + i * 0.22, 0.3);
      return <rect key={i} x={40 + i * 116} y={346} width={100} height={46} rx={23} fill={TEAL} opacity={0.18 + 0.82 * e} transform={`translate(0 ${((1 - e) * 14).toFixed(1)})`} />;
    })}
  </svg>
);
// sorriso de frente com dois dentes faltando; a peça flexível desce e encaixa
const Smile: React.FC<{ fit: number; bob: number; glow: number; piece?: number }> = ({ fit, bob, glow, piece = 1 }) => {
  const xs = (s: number) => 40 + 520 * s;
  const ys = (s: number) => 120 + 200 * s * (1 - s);
  const tooth = (i: number, dy = 0, key?: string) => {
    const s = (i + 0.5) / 8;
    const h = 92 - Math.abs(i - 3.5) * 9;
    return <rect key={key ?? i} x={xs(s) - 30} y={ys(s) - 12 + dy} width={60} height={h} rx={20} fill="#FFFFFF" stroke="#DCE4E6" strokeWidth={3} />;
  };
  const dy = (1 - fit) * -120 + bob - (1 - piece) * 160;
  return (
    <svg width={600} height={420} viewBox="0 0 600 420" style={{ overflow: "visible" }}>
      <defs>
        <clipPath id="vn-mouth">
          <path d="M40 120 Q300 400 560 120 Q300 220 40 120 Z" />
        </clipPath>
      </defs>
      <path d="M20 116 Q300 30 580 116 Q300 214 20 116 Z" fill="#C9586E" />
      <path d="M40 120 Q300 400 560 120 Q300 220 40 120 Z" fill="#5B1E2C" />
      <g clipPath="url(#vn-mouth)">
        <path d="M30 100 Q300 200 570 100 L570 140 Q300 230 30 140 Z" fill={GUM} />
        {[0, 1, 4, 5, 6, 7].map((i) => tooth(i))}
        {fit > 0.9 ? [2, 3].map((i) => tooth(i, 0, `f${i}`)) : null}
      </g>
      {fit <= 0.9 && piece > 0 ? (
        <g transform={`translate(0 ${dy.toFixed(1)})`} opacity={piece}>
          <path d={`M${xs(2 / 8) - 8} ${ys(2 / 8) - 28} L${xs(4 / 8) + 8} ${ys(4 / 8) - 28} L${xs(4 / 8) + 8} ${ys(4 / 8) - 4} L${xs(2 / 8) - 8} ${ys(2 / 8) - 4} Z`} fill={GUM} opacity={0.92} />
          {[2, 3].map((i) => tooth(i, 0, `p${i}`))}
        </g>
      ) : null}
      <path d="M40 120 Q300 400 560 120" stroke="#C9586E" strokeWidth={30} fill="none" strokeLinecap="round" />
      {glow > 0 ? (
        <g opacity={glow * (1 - Math.max(0, glow - 0.6) * 1.2)}>
          {[[xs(0.31), 196], [xs(0.47), 186], [xs(0.64), 200]].map(([x, y], i) => (
            <path key={i} d={`M${x} ${y - 30 * glow} L${x + 7} ${y - 7} L${x + 30 * glow} ${y} L${x + 7} ${y + 7} L${x} ${y + 30 * glow} L${x - 7} ${y + 7} L${x - 30 * glow} ${y} L${x - 7} ${y - 7} Z`} fill="#FFFFFF" style={{ filter: "drop-shadow(0 0 10px rgba(255,255,255,0.9))" }} />
          ))}
        </g>
      ) : null}
    </svg>
  );
};
const WaIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 48 48">
    <circle cx={24} cy={24} r={24} fill="#FFFFFF" />
    <path d="M24 10a14 14 0 0 0-12 21.2L10 38l7-1.9A14 14 0 1 0 24 10z" fill={WA} />
    <path d="M19 17c-.4-.8-.8-.8-1.1-.8h-1c-.4 0-.9.1-1.4.7-.5.5-1.8 1.7-1.8 4.2s1.8 4.9 2.1 5.3c.2.3 3.5 5.6 8.7 7.6 4.3 1.7 5.2 1.4 6.1 1.3.9-.1 3-1.2 3.4-2.4.4-1.2.4-2.2.3-2.4-.1-.2-.4-.3-1-.6l-3.4-1.6c-.5-.2-.8-.2-1.1.2-.4.5-1.3 1.6-1.6 2-.3.3-.6.4-1.1.1-.5-.2-2.1-.8-4.1-2.5-1.5-1.3-2.5-3-2.8-3.5-.3-.5 0-.8.2-1 .2-.2.5-.6.8-.9.2-.3.3-.5.5-.8.2-.4.1-.7-.1-.9z" fill="#FFFFFF" />
  </svg>
);

// ───────── transições (nunca a mesma duas vezes seguidas) ─────────
const Trans: React.FC<{ t: number; at: number; kind: "iris" | "band" | "rise" | "flash" | "side" }> = ({ t, at, kind }) => {
  const d = 0.22;
  if (t < at - d || t > at + d) return null;
  const p = lin(t, at - d, at + d);
  if (kind === "iris") {
    const r = Math.sin(p * Math.PI) * 1250;
    return <div style={{ position: "absolute", left: 540 - r, top: 900 - r, width: r * 2, height: r * 2, borderRadius: "50%", background: TEAL }} />;
  }
  if (kind === "band") {
    const x = (p * 2 - 1) * 2100;
    return <div style={{ position: "absolute", left: -360, top: -200, width: 1800, height: 2320, background: TEAL, transform: `translateX(${x.toFixed(0)}px) skewX(-14deg)`, boxShadow: `18px 0 0 ${GUM}, -18px 0 0 ${GUM}` }} />;
  }
  if (kind === "rise") {
    const y = (1 - p * 2) * 2100;
    return <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, background: INK, transform: `translateY(${y.toFixed(0)}px)`, borderTop: `22px solid ${TEAL}`, borderBottom: `22px solid ${TEAL}` }} />;
  }
  if (kind === "side") {
    const x = (1 - p * 2) * -2000;
    return <div style={{ position: "absolute", left: 0, top: -100, width: 1300, height: 2120, background: GUM, transform: `translateX(${x.toFixed(0)}px) skewY(-6deg)` }} />;
  }
  return <AbsoluteFill style={{ background: "#FFFFFF", opacity: Math.sin(p * Math.PI) * 0.95 }} />;
};

// ───────── vídeo ─────────
export const Vinicius: React.FC = () => {
  const t = useCurrentFrame() / VN_FPS;
  const band = 1590; // centro do lettering na faixa embaixo da fala
  const mid = 1360; // centro do lettering nas cenas desenhadas

  return (
    <AbsoluteFill style={{ background: "#0B1719" }}>
      {/* A · gancho em motion: sorriso com falha no "sem dente?"; depois a fala dela entra num esmaecer leve com aproximação suave */}
      <Cam t={t} a={A0} b={RET + 0.6} mode={1}>
        {t < 0.5 ? <div style={{ position: "absolute", left: 540 - 700 * k(t, 0, 0.5), top: 760 - 700 * k(t, 0, 0.5), width: 1400 * k(t, 0, 0.5), height: 1400 * k(t, 0, 0.5), borderRadius: "50%", border: `${(40 * (1 - k(t, 0, 0.5))).toFixed(1)}px solid ${TEAL}`, opacity: 1 - lin(t, 0.25, 0.5) }} /> : null}
        <AbsoluteFill style={{ transform: `scale(${(1 + [0, 2.96].reduce((sum, p) => sum + (t >= S(p) ? 0.07 * Math.exp(-(t - S(p)) * 6) : 0), 0)).toFixed(4)})`, transformOrigin: "50% 40%" }}>
          <div style={{ position: "absolute", left: 90, top: 640, width: 900, display: "flex", justifyContent: "center", transform: `scale(${(1.62 * (1.5 - 0.5 * pop(t, 0, 0.45))).toFixed(3)}) rotate(${(-6 * (1 - k(t, 0, 0.5))).toFixed(2)}deg)`, transformOrigin: "50% 40%", opacity: k(t, 0, 0.18) }}>
            <Smile fit={0} bob={0} glow={0} piece={0} />
          </div>
          <Slot
            t={t}
            top={mid + 40}
            dark
            phrases={[
              { items: [["Se", 1.56], ["você", 1.72], ["está", 2.14], ["sem", 2.56], ["dente?", 2.96, true]], end: 3.46, size: 108 },
            ]}
          />
        </AbsoluteFill>
      </Cam>
      {t >= RET && t < A1 + 0.2 ? (
        <>
          <AbsoluteFill style={{ opacity: interpolate(t, [RET, RET + 0.4], [0, 1], { ...cl, easing: Easing.inOut(Easing.cubic) }), transform: `scale(${(1.07 - 0.07 * k(t, RET, 0.9)).toFixed(4)})`, transformOrigin: "50% 36%" }}>
            <Footage t={t} a={RET} b={A1} z={[1.0, 1.06]} drift={30} punches={[4.92, 6.87]} />
          </AbsoluteFill>
          <Slot
            t={t}
            top={band}
            phrases={[
              { items: [["Quer", 3.58], ["uma", 3.78], ["solução", 3.96], ["rápida", 4.92, true]], end: 5.6 },
              { items: [["e", 5.61], ["sem", 5.81, true], ["dor?", 6.09, true]], end: 6.84, size: 120 },
              { items: [["Esse", 6.87], ["recado", 7.13], ["é", 7.49], ["pra", 7.53], ["você", 7.71, true]], end: 8.5 },
            ]}
          />
        </>
      ) : null}

      {/* B · a prótese flexível desenhada */}
      <Cam t={t} a={A1} b={S(13.9)} mode={0}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 300, display: "flex", justifyContent: "center", opacity: k(t, S(11.61), 0.35) }}>
          <Label size={44}>Prótese flexível</Label>
        </div>
        <div style={{ position: "absolute", left: 120, top: 430, width: 840, display: "flex", justifyContent: "center", transform: `scale(${(1.3 * (0.6 + 0.4 * pop(t, S(8.69), 0.6))).toFixed(3)}) translateY(${(Math.sin(t * 1.6) * 6).toFixed(1)}px)`, transformOrigin: "50% 40%", opacity: k(t, S(8.69), 0.3) }}>
          <Prosthesis teethIn={lin(t, S(9.03), S(10.4))} />
        </div>
        <Slot
          t={t}
          top={mid}
          dark
          phrases={[
            { items: [["Prótese", 9.03], ["flexível", 9.55, true]], end: 11.58, size: 112 },
            { items: [["100%", 11.61, true], ["estética", 12.29]], end: 14.2, size: 112 },
          ]}
        />
      </Cam>
      <Cam t={t} a={S(13.9)} b={B1} mode={1}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 300, display: "flex", justifyContent: "center" }}>
          <Label size={44}>Prótese flexível</Label>
        </div>
        <div style={{ position: "absolute", left: 120, top: 430, width: 840, display: "flex", justifyContent: "center", transform: `scale(1.3)`, transformOrigin: "50% 40%" }}>
          <Prosthesis flex={Math.max(0, Math.sin(lin(t, S(14.11), S(15.2)) * Math.PI * 2)) + 0.5 * Math.max(0, Math.sin(lin(t, S(15.28), S(16.1)) * Math.PI))} />
        </div>
        {t > S(16.9) - 0.05 && t < S(18.36) ? (
          <div style={{ position: "absolute", left: 390, top: 640, transform: `scale(${pop(t, S(16.9), 0.4).toFixed(3)}) rotate(${(-8 + 8 * k(t, S(16.9), 0.5)).toFixed(1)}deg)`, opacity: 1 - interpolate(t, [S(18.36) - 0.15, S(18.36)], [0, 1], cl) }}>
            <Clasp strike={k(t, S(17.28), 0.3)} />
          </div>
        ) : null}
        <Slot
          t={t}
          top={mid}
          dark
          phrases={[
            { items: [["Macia", 14.11, true]], end: 15.26, size: 140 },
            { items: [["Confortável", 15.28, true]], end: 16.88, size: 132 },
            { items: [["Sem", 16.9], ["grampo", 17.28, true]], end: 18.34, size: 124 },
            { items: [["Não", 18.36], ["machuca", 18.54, true]], end: 19.6, size: 124 },
