      </Cam>

      {/* C · fala: para quem não pode fazer implante */}
      <Footage t={t} a={B1} b={C1} z={[1.1, 1.02]} drift={-40} punches={[22.84]} />
      {t >= B1 && t < C1 + 0.2 ? (
        <Slot
          t={t}
          top={band}
          phrases={[
            { items: [["Não", 20.26], ["pode", 20.6], ["fazer", 21.02], ["implante?", 21.66, true]], end: 22.8 },
            { items: [["Opção", 22.84], ["ideal", 23.28, true], ["pra", 23.7], ["você", 23.88]], end: 25.0 },
