        />
      ) : null}

      {/* D · preço justo e parcelas, sem números */}
      <Cam t={t} a={C1} b={D1} mode={2}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 470, height: 520, display: "flex", justifyContent: "center", alignItems: "center" }}>
          {t < S(27.95) ? (
            <div style={{ transform: `scale(${(1.35 * pop(t, S(24.96), 0.5)).toFixed(3)}) rotate(${(-10 + 10 * k(t, S(24.96), 0.6)).toFixed(1)}deg)`, opacity: 1 - interpolate(t, [S(27.95) - 0.15, S(27.95)], [0, 1], cl) }}>
              <Tag />
            </div>
          ) : t < S(30.91) ? (
            <div style={{ transform: `scale(${(1.3 * pop(t, S(27.95), 0.45)).toFixed(3)})`, opacity: 1 - interpolate(t, [S(30.91) - 0.15, S(30.91)], [0, 1], cl) }}>
              <Wallet coin={k(t, S(28.5), 0.55)} />
            </div>
          ) : (
            <div style={{ transform: `scale(${(1.2 * pop(t, S(30.91), 0.45)).toFixed(3)}) translateY(${((1 - k(t, S(30.91), 0.5)) * 80).toFixed(1)}px)` }}>
              <Card t={t} at={S(31.55)} />
            </div>
          )}
        </div>
        <Slot
          t={t}
          top={mid}
          dark
          phrases={[
            { items: [["Não", 24.96], ["é", 25.22], ["cara", 25.4, true]], end: 26.46, size: 124 },
            { items: [["Preço", 26.48], ["justo", 27.12, true]], end: 27.93, size: 124 },
            { items: [["Cabe", 27.95], ["no", 28.25], ["seu", 28.43], ["bolso", 28.63, true]], end: 30.89, size: 112 },
            { items: [["Parcelas", 30.91], ["facilitadas", 31.55, true]], end: 33.5, size: 110 },
          ]}
        />
      </Cam>

      {/* E · fala: medo de dentista */}
      <Footage t={t} a={D1} b={E1} z={[1.0, 1.1]} drift={36} punches={[37.59]} />
      {t >= D1 && t < E1 + 0.2 ? (
        <Slot
          t={t}
          top={band}
          phrases={[
            { items: [["Medo", 34.63], ["de", 34.87], ["dentista?", 35.03, true]], end: 37.56 },
            { items: [["Não", 37.59], ["dói", 37.85], ["nada", 38.53, true]], end: 39.2, size: 120 },
          ]}
        />
      ) : null}

      {/* F · o sorriso: a peça desce e encaixa */}
      <Cam t={t} a={E1} b={F1} mode={0}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 300, display: "flex", justifyContent: "center", opacity: k(t, S(39.47), 0.35) }}>
          <Label size={44}>Prótese flexível</Label>
        </div>
        <div style={{ position: "absolute", left: 90, top: 600, width: 900, display: "flex", justifyContent: "center", transform: `scale(${(1.62 * (0.75 + 0.25 * pop(t, E1, 0.5))).toFixed(3)})`, transformOrigin: "50% 40%", opacity: k(t, E1, 0.25) }}>
          <Smile fit={k(t, S(43.42), 0.35)} bob={t < S(43.42) ? Math.sin(t * 3) * 10 * k(t, S(39.47), 0.5) : 0} glow={lin(t, S(43.6), S(44.8))} />
        </div>
        <Slot
          t={t}
          top={mid}
          dark
          phrases={[
            { items: [["100%", 40.47, true], ["confortável", 41.17]], end: 42.6, size: 108 },
            { items: [["Se", 42.59], ["adapta", 42.67, true], ["ao", 44.38], ["seu", 44.54], ["sorriso", 44.76]], end: 45.7, size: 104 },
          ]}
        />
      </Cam>

      {/* G · fala: chamada para o WhatsApp */}
      <Footage t={t} a={F1} b={G1} z={[1.06, 1.14]} drift={-30} punches={[47.1]} />
      {t >= F1 && t < G1 + 0.2 ? (
        <Slot
          t={t}
          top={band}
          phrases={[
            { items: [["Ficou", 46.02], ["interessado?", 46.26, true]], end: 47.08 },
            { items: [["Chama", 47.1], ["no", 47.84], ["WhatsApp", 47.9, true]], end: 48.9 },
          ]}
        />
      ) : null}

      {/* fim: cartão final */}
      <Cam t={t} a={G1} b={VN_DUR} mode={2}>
        <div style={{ position: "absolute", left: 120, top: 400, width: 840, display: "flex", justifyContent: "center", transform: `scale(${(1.15 * pop(t, G1 + 0.05, 0.6)).toFixed(3)})`, transformOrigin: "50% 40%" }}>
          <Prosthesis />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1080, display: "flex", flexDirection: "column", alignItems: "center", gap: 34 }}>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 92, lineHeight: 1, color: INK, textTransform: "uppercase", ...{ opacity: k(t, G1 + 0.2, 0.35), transform: `translateY(${((1 - k(t, G1 + 0.2, 0.35)) * 40).toFixed(1)}px)` } }}>Prótese flexível</div>
          <div style={{ display: "flex", gap: 16, opacity: k(t, G1 + 0.5, 0.35) }}>
            {["Sem grampo", "Sem dor", "Parcelas facilitadas"].map((s, i) => (
              <div key={i} style={{ fontFamily: F, fontWeight: 600, fontSize: 38, color: TEAL_D, background: "#FFFFFF", border: `3px solid ${TEAL}33`, borderRadius: 40, padding: "10px 24px 12px", whiteSpace: "nowrap", opacity: k(t, G1 + 0.5 + i * 0.14, 0.3) }}>
                {s}
              </div>
            ))}
          </div>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1400, display: "flex", justifyContent: "center" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 26, background: WA, borderRadius: 80, padding: "26px 54px 28px 34px", boxShadow: "0 18px 44px rgba(37,211,102,0.4)", transform: `scale(${pop(t, G1 + 0.8, 0.5).toFixed(3)})` }}>
            <WaIcon s={92} />
            <div style={{ fontFamily: F, fontWeight: 800, fontSize: 64, color: "#FFFFFF", textTransform: "uppercase", whiteSpace: "nowrap" }}>Chama no WhatsApp</div>
          </div>
        </div>
      </Cam>

      <Trans t={t} at={A1} kind="iris" />
      <Trans t={t} at={S(13.9)} kind="side" />
      <Trans t={t} at={B1} kind="band" />
      <Trans t={t} at={C1} kind="rise" />
      <Trans t={t} at={D1} kind="flash" />
      <Trans t={t} at={E1} kind="iris" />
      <Trans t={t} at={F1} kind="band" />
      <Trans t={t} at={G1} kind="rise" />
    </AbsoluteFill>
  );
};

